    func testReviewRewardOwnsDailyGoalOrderingAndReplayedScoreCannotReplaceReceipt()throws {
        try isolated();let app=AppModel(progressService:RPGCompletionNoCloud());try app.identity.create();defer{try? app.identity.disconnect()};app.signedIn=true;app.subscription.bind(app.identity);app.learner=LearnerState();app.learner.onboardingComplete=true;app.learner.target="es";app.learner.dailyGoal=30
        let units=try ContentLibrary.load([String:[LearningUnit]].self,name:"curriculum-es"),lesson=try XCTUnwrap(units["Pre-A1"]?.flatMap(\.lessons).first{$0.id == "unit-pre-a1-people-game"}),library=try ContentLibrary.load(RPGLibrary.self,name:"rpg-es"),scenario=try XCTUnwrap(library.reviews[lesson.id]?.bySupport["en"])
        var run=RPGRun(target:"es",support:"en",lessonID:lesson.id,xpReward:30,scenario:scenario,world:try XCTUnwrap(library.worlds[scenario.worldKey]));run.stepIndex=run.scenario.quest.steps.count;run.score=800;app.learner.saveRPG(run)
        let controller=PlatePracticeController();controller.bind(app);defer{controller.unbind()};app.lessonActivityActive=true
        app.completeGameReview(run,lesson:lesson);let presentation=try XCTUnwrap(app.pendingLessonCompletion);XCTAssertEqual(presentation.reward,30);XCTAssertEqual(presentation.languageXP,30);XCTAssertNotNil(app.dailyGoalReward);XCTAssertNil(controller.dailyGoalVisible,"The lesson owns completion before XP observers release the daily goal")
        app.lessonActivityActive=false;controller.presentationBlocked(false,app:app);XCTAssertNil(controller.dailyGoalVisible,"Dismissing the game must not bypass the unacknowledged lesson bonus")
        app.pendingLessonCompletion=nil;controller.presentationBlocked(false,app:app);XCTAssertNotNil(controller.dailyGoalVisible);controller.closeDailyGoal(app)
        let encoder=JSONEncoder();encoder.outputFormatting = .sortedKeys;let receipt=try encoder.encode(app.learner.pendingChanges?.filter{$0.source == .lesson})
        var replay=run;replay.id=UUID();replay.score=700;app.learner.saveRPG(replay);app.completeGameReview(replay,lesson:lesson);XCTAssertEqual(app.learner.totalXP,30);XCTAssertEqual(app.learner.rpgRuns?["es"]?.claimed,true);XCTAssertNil(app.pendingLessonCompletion);XCTAssertNil(app.dailyGoalReward);XCTAssertEqual(try encoder.encode(app.learner.pendingChanges?.filter{$0.source == .lesson}),receipt)
    }
